-- ============================================================================
-- wines_catalog — wines listed by BC Liquor Stores, round 2 (Canada, Chile,
-- Argentina, Portugal, New Zealand, South Africa and smaller countries). Source:
-- BC Liquor Store Product Price List, August 2026 edition,
-- https://catalogue.data.gov.bc.ca/dataset/bc-liquor-store-product-price-list-historical-prices
-- Contains information licensed under the Open Government Licence – British Columbia.
-- A liquor-board listing proves the wine exists, so every row is 'verified'
-- (verified_source 'bc-liquor'), with its BC SKU(s) in verification_notes.
-- Idempotent: safe to run more than once.
-- ============================================================================
insert into public.wines_catalog (producer, wine_name, region, grape, style, display, source, verification_status, verified_source, verified_at, verification_notes)
select p, w, r, g, s, trim(p || ' ' || coalesce(w, '')), 'bc-liquor', 'verified', 'bc-liquor', now(), n
from (values
  ('Finca los Primos', 'Malbec Cabernet', 'Mendoza, Argentina', 'Malbec, Cabernet Sauvignon', 'Red', 'BC Liquor Stores product price list (Aug 2026 edition, BC Data Catalogue). Contains information licensed under the Open Government Licence – British Columbia. SKU 611772'),
